import pandas as pd
import matplotlib.pyplot as plt

def generate_f1_dashboard():
    # 1. Load CSV data generated by the C++ engine
    df_laps = pd.read_csv('lap_times.csv')
    df_mc = pd.read_csv('monte_carlo_results.csv')

    # Configure elegant dark style
    plt.style.use('dark_background')
    fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(18, 9))
    fig.suptitle('F1 Multi-Driver Strategy & Telemetry Dashboard', fontsize=18, fontweight='bold', color='white')

    # Driver names mapped to grid order
    driver_names = ['Verstappen (Soft->Hard)', 'Leclerc (Med->Hard)', 'Norris (Med->Soft)']
    colors = ['#FF1801', '#FFF500', '#FF8700'] # Constructor colors (Red, Yellow, Orange)

    competitor_cols = [col for col in df_laps.columns if col != 'Lap']

    # --- PLOT 1: Single Race Telemetry (Strategy Comparison) ---
    for i, col in enumerate(competitor_cols):
        name = driver_names[i] if i < len(driver_names) else f'Comp {i}'
        color = colors[i % len(colors)]
        ax1.plot(df_laps['Lap'], df_laps[col], color=color, linewidth=2, label=name, alpha=0.85)

    ax1.set_title('Single Race Telemetry (Strategy Comparison)', fontsize=14)
    ax1.set_xlabel('Lap Number', fontsize=12)
    ax1.set_ylabel('Lap Time (Seconds)', fontsize=12)
    ax1.grid(True, linestyle='--', alpha=0.3)
    ax1.legend(loc='upper right', fontsize=11)

    # --- PLOT 2: Monte Carlo Distribution (Total Race Times) ---
    mc_cols = [col for col in df_mc.columns if col != 'SimulationID']
    
    for i, col in enumerate(mc_cols):
        name = driver_names[i] if i < len(driver_names) else f'Comp {i}'
        color = colors[i % len(colors)]
        times_in_minutes = df_mc[col] / 60.0
        
        ax2.hist(times_in_minutes, bins=50, alpha=0.4, color=color, 
                 label=f'{name} (Mean: {times_in_minutes.mean():.2f} min)')

    ax2.set_title('Monte Carlo Distribution (10000 Sims - Race Pace)', fontsize=14)
    ax2.set_xlabel('Total Race Time (Minutes)', fontsize=12)
    ax2.set_ylabel('Frequency', fontsize=12)
    ax2.grid(True, linestyle='--', alpha=0.3)
    ax2.legend(loc='upper right', fontsize=11)

    plt.tight_layout()
    plt.show()

if __name__ == "__main__":
    generate_f1_dashboard()